import{_ as t,o,c as a,a5 as l}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Sequence Flow — Save Workspace Template","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-17-save-workspace-template/sequence-flow.md","filePath":"feature/agency-workspace/3-4-17-save-workspace-template/sequence-flow.md"}'),c={name:"feature/agency-workspace/3-4-17-save-workspace-template/sequence-flow.md"};function r(d,e,s,i,p,n){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="sequence-flow-—-save-workspace-template" tabindex="-1">Sequence Flow — Save Workspace Template <a class="header-anchor" href="#sequence-flow-—-save-workspace-template" aria-label="Permalink to &quot;Sequence Flow — Save Workspace Template&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.17). <code>WorkspaceTemplateServiceImpl</code> is &gt; <strong>implemented</strong> — all four methods (<code>saveTemplate</code>, <code>listTemplates</code>, &gt; <code>getTemplate</code>, <code>deleteTemplate</code>) run real logic; none throws &gt; <code>UnsupportedOperationException</code> anymore. &gt; &gt; Updated: 2026-09-25.</p><h2 id="actors-lifelines" tabindex="-1">Actors / Lifelines <a class="header-anchor" href="#actors-lifelines" aria-label="Permalink to &quot;Actors / Lifelines&quot;">​</a></h2><ul><li><strong>Member</strong> — a signed-in Agency member, acting from Workspace settings (<code>detail.tsx</code>) or the templates list page (<code>templates.tsx</code>, <code>/workspaces/templates</code>).</li><li><strong>WorkspaceTemplateController</strong> — <code>saveTemplate</code> / <code>listTemplates</code> / <code>getTemplate</code> / <code>deleteTemplate</code> endpoints.</li><li><strong>WorkspaceTemplateServiceImpl</strong> — real business logic; resolves the caller&#39;s owned Agency via <code>resolveOwnedAgencyId</code> (same pattern as <code>WorkspaceServiceImpl.listMyWorkspaces</code>).</li><li><strong>WorkspaceTemplateRepository</strong> — persistence for <code>WorkspaceTemplate</code>.</li><li><strong>AgencyRepository</strong> — resolves the caller&#39;s owned Agency (<code>findByOwnerIdAndStatusNot</code>).</li></ul><hr><h2 id="flow-a-—-save-a-template" tabindex="-1">Flow A — Save a template <a class="header-anchor" href="#flow-a-—-save-a-template" aria-label="Permalink to &quot;Flow A — Save a template&quot;">​</a></h2><ol><li>Member → WorkspaceTemplateController: in the &quot;Save as Template&quot; modal (<code>detail.tsx</code>), supplies a name; <code>configSnapshot</code> is auto-built from <code>timezone</code>/<code>defaultPlatforms</code>/<code>reportFrequency</code> and <code>sourceWorkspaceId</code> is set to the current workspace id. <code>POST /api/v1/workspace-templates</code>.</li><li>WorkspaceTemplateController: validates <code>name</code>/<code>configSnapshot</code> not empty via <code>@NotBlank</code> on <code>SaveWorkspaceTemplateRequest</code> → 400 <code>VALIDATION_ERROR</code> if either is empty.</li><li>WorkspaceTemplateController → WorkspaceTemplateServiceImpl: <code>saveTemplate(currentUser, request)</code>.</li><li>WorkspaceTemplateServiceImpl → AgencyRepository: <code>resolveOwnedAgencyId(currentUser)</code> — <code>findByOwnerIdAndStatusNot(currentUser.getId(), SOFT_DELETED)</code>; no owned Agency → 404 <code>AGENCY_NOT_FOUND</code>.</li><li>WorkspaceTemplateServiceImpl: builds a <code>WorkspaceTemplate</code> with <code>agencyId</code>/<code>createdBy</code> set from the resolved Agency and <code>currentUser</code> — never from the request payload (BR-29).</li><li>WorkspaceTemplateServiceImpl → WorkspaceTemplateRepository: <code>save(template)</code>.</li><li>WorkspaceTemplateServiceImpl → WorkspaceTemplateController → Member: 200 with the stored <code>WorkspaceTemplateResponse</code>.</li><li>Member (FE, on success): success toast, modal closes.</li></ol><h2 id="flow-b-—-list-templates" tabindex="-1">Flow B — List templates <a class="header-anchor" href="#flow-b-—-list-templates" aria-label="Permalink to &quot;Flow B — List templates&quot;">​</a></h2><ol><li>Member → WorkspaceTemplateController: opens <code>/workspaces/templates</code>; <code>GET /api/v1/workspace-templates</code>.</li><li>WorkspaceTemplateController → WorkspaceTemplateServiceImpl: <code>listTemplates(currentUser)</code>.</li><li>WorkspaceTemplateServiceImpl → AgencyRepository: <code>resolveOwnedAgencyId(currentUser)</code> — no owned Agency → 404 <code>AGENCY_NOT_FOUND</code>.</li><li>WorkspaceTemplateServiceImpl → WorkspaceTemplateRepository: <code>findByAgencyId(agencyId)</code> → the caller&#39;s Agency-scoped templates.</li><li>WorkspaceTemplateServiceImpl → WorkspaceTemplateController → Member: the list of templates.</li></ol><h2 id="flow-c-—-inline-expand-to-view-a-template-no-separate-detail-route" tabindex="-1">Flow C — Inline expand to view a template (no separate detail route) <a class="header-anchor" href="#flow-c-—-inline-expand-to-view-a-template-no-separate-detail-route" aria-label="Permalink to &quot;Flow C — Inline expand to view a template (no separate detail route)&quot;">​</a></h2><ol><li>Member → FE only: clicks a template&#39;s name in the already-loaded list; FE toggles showing that template&#39;s <code>configSnapshot</code> inline. No network call — the detail data was already fetched by Flow B&#39;s list response. There is no dedicated detail URL in the UI.</li></ol><h2 id="flow-c-1-—-get-a-single-template-get-templateid-api-level-not-wired-into-the-current-ui-flow" tabindex="-1">Flow C.1 — Get a single template (<code>GET /{templateId}</code>, API-level; not wired into the current UI flow) <a class="header-anchor" href="#flow-c-1-—-get-a-single-template-get-templateid-api-level-not-wired-into-the-current-ui-flow" aria-label="Permalink to &quot;Flow C.1 — Get a single template (`GET /{templateId}`, API-level; not wired into the current UI flow)&quot;">​</a></h2><ol><li>Caller → WorkspaceTemplateController: <code>GET /api/v1/workspace-templates/{templateId}</code>.</li><li>WorkspaceTemplateController → WorkspaceTemplateServiceImpl: <code>getTemplate(templateId, currentUser)</code>.</li><li>WorkspaceTemplateServiceImpl → WorkspaceTemplateRepository: <code>findById(templateId)</code> → missing → 404 <code>NOT_FOUND</code>.</li><li>WorkspaceTemplateServiceImpl → AgencyRepository: <code>resolveOwnedAgencyId(currentUser)</code>; compares against <code>template.getAgencyId()</code> — mismatch → 403 <code>FORBIDDEN</code> (Agency-scope check, patched in this pass — previously missing).</li><li>WorkspaceTemplateServiceImpl → WorkspaceTemplateController → Caller: 200 with the <code>WorkspaceTemplateResponse</code>.</li></ol><h2 id="flow-d-—-delete-a-template" tabindex="-1">Flow D — Delete a template <a class="header-anchor" href="#flow-d-—-delete-a-template" aria-label="Permalink to &quot;Flow D — Delete a template&quot;">​</a></h2><ol><li>Member → WorkspaceTemplateController: clicks the delete (trash) icon on a template row; <code>DELETE /api/v1/workspace-templates/{templateId}</code>.</li><li>WorkspaceTemplateController → WorkspaceTemplateServiceImpl: <code>deleteTemplate(templateId, currentUser)</code>.</li><li>WorkspaceTemplateServiceImpl → WorkspaceTemplateRepository: <code>findById(templateId)</code> → missing → 404 <code>NOT_FOUND</code>.</li><li>WorkspaceTemplateServiceImpl → AgencyRepository: <code>resolveOwnedAgencyId(currentUser)</code>; compares against <code>template.getAgencyId()</code> — mismatch → 403 <code>FORBIDDEN</code>.</li><li>WorkspaceTemplateServiceImpl → WorkspaceTemplateRepository: <code>delete(template)</code>.</li><li>WorkspaceTemplateServiceImpl → WorkspaceTemplateController → Member: 200 confirmation; FE removes the row from the list and shows a success toast.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>Status</th><th>Error code</th></tr></thead><tbody><tr><td>Create</td><td><code>name</code> empty</td><td>400</td><td><code>VALIDATION_ERROR</code></td></tr><tr><td>Create</td><td><code>configSnapshot</code> empty</td><td>400</td><td><code>VALIDATION_ERROR</code></td></tr><tr><td>Create / List / Get / Delete</td><td>Caller has no owned Agency</td><td>404</td><td><code>AGENCY_NOT_FOUND</code></td></tr><tr><td>Get / Delete</td><td>Template does not exist</td><td>404</td><td><code>NOT_FOUND</code></td></tr><tr><td>Get / Delete</td><td>Template belongs to a different Agency</td><td>403</td><td><code>FORBIDDEN</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>All four <code>WorkspaceTemplateServiceImpl</code> methods are implemented; the earlier stub (<code>UnsupportedOperationException</code>) is resolved.</li><li><code>getTemplate</code> now enforces the same Agency-scope check as <code>deleteTemplate</code> (patched in this pass — previously only <code>deleteTemplate</code> had it).</li><li>Templates are a standalone resource, not nested inside an Agency or a Workspace.</li><li>No specific role restriction is currently applied to these actions (BR-05) — still to be confirmed, independent of the (now-resolved) stub issue.</li><li>The &quot;detail&quot; view surfaced in the UI is an inline expand within the templates list page (Flow C), not the <code>GET /{templateId}</code> endpoint (Flow C.1), which exists at the API level but is not called by the current FE.</li></ul>',20)])])}const u=t(c,[["render",r]]);export{h as __pageData,u as default};
